package htt.pseudorandomometricsequencesapi.domain.multivariate

import org.apache.commons.math3.distribution.GammaDistribution
import org.apache.commons.math3.random.RandomGenerator
import org.springframework.stereotype.Component

/**
 * Joint Dirichlet distribution.
 *
 * <p>Each sample is a probability vector whose components are non-negative and sum to 1.
 * Samples are generated by drawing independent Gamma(α_i, 1) values and normalizing
 * them by their sum.</p>
 */
class DirichletGenerator(
    concentration: DoubleArray,
    randomGenerator: RandomGenerator
) : MultivariateSequenceGenerator {

    override val dimension: Int = concentration.size
    private val gammaDistributions: List<GammaDistribution>

    init {
        require(concentration.isNotEmpty()) {
            "Dirichlet 'concentration' must not be empty."
        }
        require(concentration.all { it > 0.0 && it.isFinite() }) {
            "Dirichlet 'concentration' values must be positive and finite."
        }
        gammaDistributions = concentration.map { GammaDistribution(randomGenerator, it, 1.0) }
    }

    override fun sample(): DoubleArray {
        repeat(MAX_ATTEMPTS) {
            val values = DoubleArray(dimension) { gammaDistributions[it].sample() }
            val sum = values.sum()
            if (sum > 0.0 && sum.isFinite()) {
                return DoubleArray(dimension) { values[it] / sum }
            }
        }
        throw IllegalStateException(
            "Unable to sample the Dirichlet distribution with the supplied concentration."
        )
    }

    private companion object {
        const val MAX_ATTEMPTS = 100
    }
}

@Component
class DirichletFactory : MultivariateDistributionFactory {

    override val name = "dirichlet"

    override val description =
        "concentration = concentration vector α (all values > 0); samples are probability vectors summing to 1"

    override fun create(
        spec: MultivariateSpec,
        javaRandom: java.util.Random,
        commonsRandom: RandomGenerator
    ): MultivariateSequenceGenerator {
        val concentration = spec.concentration
            ?: throw IllegalArgumentException("Dirichlet requires 'concentration'.")

        return DirichletGenerator(
            concentration = concentration.toDoubleArray(),
            randomGenerator = commonsRandom
        )
    }
}
